function interaction(i,source){let l=lead(i);if(!active(l)){toast('Reactivate this lead first.');return}sheet(`<h2>Record ${esc(l.name)}</h2><form id="int" class="form-grid"><div class="field"><label>Type</label>${opts(['Greeting / check-in','Sales conversation'],'kind')}</div><div class="field"><label>What happened?</label><textarea name="summary" required autofocus></textarea></div><div id="sales"><div class="field"><label>Outcome</label>${opts(['Follow up','Not interested','Converted'],'outcome')}</div><div id="next"><div class="field"><label>Contact next by</label>${opts(['Call','WhatsApp','Instagram DM'],'channel')}</div><div class="field"><label>Next follow-up</label>${opts(['Tomorrow','2 days','3 days','1 week','2 weeks','Pick date'],'when')}<input id="whenDate" type="date" min="${today()}" hidden></div></div></div><div class="field"><label>Remember</label><textarea name="memory"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="closeSheet()">Cancel</button><button class="primary">Save</button></div></form>`);$('#sales').hidden=true;bind('#kind',v=>$('#sales').hidden=v!=='Sales conversation');bind('#outcome',v=>$('#next').hidden=v!=='Follow up');bind('#when',v=>$('#whenDate').hidden=v!=='Pick date');$('#int').onsubmit=e=>{e.preventDefault();let x=new FormData(e.target),k=choice('#kind'),t=db.tasks.find(t=>t.id===source);if(t)done(t,'handled');let via=k==='Sales conversation'&&choice('#outcome')==='Follow up'?choice('#channel').toLowerCase():'';l.interactions.push({id:id(),date:today(),kind:k==='Greeting / check-in'?'greeting':'sales conversation',summary:x.get('summary').trim(),nextContactVia:via});if(x.get('memory').trim())l.memory=x.get('memory').trim();if(k==='Sales conversation'){let o=choice('#outcome');if(o==='Converted'){l.converted=true;closeFor(i,'converted')}else if(o==='Not interested'){l.noReply=true;closeFor(i,'paused')}else{let w=choice('#when'),m={Tomorrow:1,'2 days':2,'3 days':3,'1 week':7,'2 weeks':14},d=w==='Pick date'?$('#whenDate').value:add(m[w]);if(!d||d<today()){toast('Choose a valid future date.');return}schedule(i,via==='whatsapp'?'text':via==='instagram dm'?'dm':'call',d,source)}}save();closeSheet();render();toast('Interaction recorded.')}}
function reschedule(i){let t=db.tasks.find(x=>x.id===i);sheet(`<h2>Reschedule</h2><form id="rs" class="form-grid"><div class="field"><label>New date</label><input id="rd" type="date" min="${today()}" value="${t.date<today()?today():t.date}" required></div><div class="field"><label>Reason</label><input id="rr" placeholder="Optional"></div><div class="sheet-footer"><button type="button" class="secondary" onclick="openTask('${i}')">Cancel</button><button class="primary">Save</button></div></form>`);$('#rs').onsubmit=e=>{e.preventDefault();t.date=$('#rd').value;t.rescheduleReason=$('#rr').value;save();closeSheet();render();toast('Task rescheduled.')}}
function openTask(i){let t=db.tasks.find(x=>x.id===i),l=lead(t?.leadId);if(!t)return;if(t.type==='ai_review'){sheet(`<h2>Daily AI prep</h2><p class="intro">Prepare guidance before outreach. You can skip it today.</p><div class="sheet-footer"><button class="secondary" onclick="copyPrompt()">Copy prompt</button><button class="primary" onclick="aiJsonSheet()">Paste AI JSON</button></div><button class="add-general" onclick="completeTask('${i}')">Skip for today</button>`);return}if(t.type==='call'&&l){sheet(`<h2>Call ${esc(l.name)}</h2><p class="intro">${esc(l.contact)}</p><div class="notice"><b>Brief</b><br>${esc(t.ai?.pre_call_brief||'Review the history, then agree one next step.')}<br><br><b>Goal</b><br>${esc(t.ai?.call_goal||'Understand their situation and agree one next action.')}</div><div class="sheet-footer"><button class="secondary" onclick="profile('${l.id}')">History</button><button class="primary" onclick="interaction('${l.id}','${i}')">Record call</button></div><button class="add-general" onclick="reschedule('${i}')">Reschedule</button>`);return}if(t.type==='text'&&l){sheet(`<h2>Text ${esc(l.name)}</h2><p class="intro">Copy, send it yourself, then mark sent.</p><div class="field"><label>Message</label><textarea id="msg">${esc(t.ai?.exact_message||'')}</textarea></div><div class="sheet-footer"><button class="secondary" id="copy">Copy</button><button class="primary" id="sent">Mark sent</button></div><button class="add-general" onclick="reschedule('${i}')">Reschedule</button>`);$('#copy').onclick=()=>navigator.clipboard.writeText($('#msg').value).then(()=>toast('Text copied.')).catch(()=>toast('Copy manually.'));$('#sent').onclick=()=>{let m=$('#msg').value.trim();if(!m){toast('Write or generate a message first.');return}t.ai={...(t.ai||{}),exact_message:m};done(t,'sent');l.interactions.push({id:id(),date:today(),kind:'text sent',summary:m});schedule(l.id,'text_feedback',add(1),i);save();closeSheet();render();toast('Sent; reply check is due tomorrow.')} ;return}if(t.type==='text_feedback'&&l){sheet(`<h2>Reply check: ${esc(l.name)}</h2><div class="form-grid"><button class="secondary" id="yes">They replied</button><button class="secondary" id="no">No response yet</button><button class="secondary" id="call">Spoke on call</button><button class="danger" id="pause">Pause follow-ups</button></div><button class="add-general" onclick="reschedule('${i}')">Reschedule check</button>`);$('#yes').onclick=()=>{done(t,'replied');save();closeSheet();interaction(l.id,i)};$('#call').onclick=()=>{done(t,'spoke');save();closeSheet();interaction(l.id,i)};$('#no').onclick=()=>{done(t,'no-reply');let n=(t.replyChecks||0)+1,q=schedule(l.id,n>=3?'text':'text_feedback',n>=3?today():add(2),i);q.replyChecks=n;save();closeSheet();render();toast(n>=3?'Final follow-up text is ready.':'Reply check moved by 2 days.')};$('#pause').onclick=()=>setState(l.id,'paused');return}sheet(`<h2>${esc(t.title)}</h2><div class="field"><label>Notes</label><textarea id="note">${esc(t.note||'')}</textarea></div><div class="sheet-footer"><button class="danger" onclick="completeTask('${i}')">Delete</button><button class="primary" id="saveTask">Save</button></div><button class="add-general" onclick="reschedule('${i}')">Reschedule</button>`);$('#saveTask').onclick=()=>{t.note=$('#note').value;save();closeSheet();render()}}
function completeTask(i){let t=db.tasks.find(x=>x.id===i);if(['call','text','text_feedback'].includes(t.type)){openTask(i);return}done(t);save();closeSheet();render();toast('Done.')}
function addGeneral(){sheet(`<h2>Personal to-do</h2><form id="g" class="form-grid"><div class="field"><label>What?</label><input name="title" required autofocus></div><div class="field"><label>When?</label><input name="date" type="date" min="${today()}" value="${today()}" required></div><div class="field"><label>Notes</label><textarea name="note"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="closeSheet()">Cancel</button><button class="primary">Add</button></div></form>`);$('#g').onsubmit=e=>{e.preventDefault();let x=new FormData(e.target);db.tasks.push({id:id(),type:'general',title:x.get('title'),note:x.get('note'),date:x.get('date'),done:false});save();closeSheet();render()}}
function promptTasks(){return due().filter(t=>['call','text'].includes(t.type)&&lead(t.leadId))}function copyPrompt(ts=promptTasks()){let data=ts.map(t=>{let l=lead(t.leadId);return{task_id:t.id,name:l.name,interest:l.interest,history:l.interactions.map(i=>`${i.date} ${i.kind}: ${i.summary}`),remember:l.memory||'',current_task:t.type}}),p=`Business context:\n${db.context||'(none)'}\n\nReturn ONLY a JSON array. Keep task_id exactly. Schema: [{"task_id":"exact id","recommended_channel":"call or text","exact_message":"ready-to-send text or empty","pre_call_brief":"short factual brief","call_goal":"one clear goal","next_best_action":"short action"}]\n\nTASKS:\n${JSON.stringify(data,null,2)}`;navigator.clipboard.writeText(p).then(()=>toast('Prompt copied. Paste AI JSON when ready.')).catch(()=>toast('Clipboard blocked; copy manually.'))}
function aiJsonSheet(){sheet(`<h2>Apply AI guidance</h2><p class="intro">Only task IDs from today’s prompt are accepted. Nothing sends automatically.</p><div class="field"><label>AI JSON</label><textarea id="json"></textarea></div><div class="sheet-footer"><button class="secondary" onclick="closeSheet()">Cancel</button><button class="primary" id="review">Review</button></div>`);$('#review').onclick=()=>{let a;try{a=JSON.parse($('#json').value);if(!Array.isArray(a))throw 0}catch{toast('Paste a valid JSON array.');return}let allowed=new Set(promptTasks().map(t=>t.id)),changes=a.filter(x=>x&&x.task_id&&allowed.has(x.task_id)&&x.recommended_channel&&['call','text'].includes(String(x.recommended_channel).toLowerCase()));if(!changes.length){toast('No matching task IDs. Copy a fresh prompt first.');return}sheet(`<h2>Review guidance</h2><p class="intro">${changes.length} task${changes.length===1?'':'s'} will change.</p>${changes.map(x=>{let t=db.tasks.find(t=>t.id===x.task_id),l=lead(t.leadId);return `<div class="notice"><b>${esc(l.name)} → ${esc(x.recommended_channel)}</b><br>${esc(x.recommended_channel==='text'?x.exact_message:x.call_goal||x.pre_call_brief)}</div>`}).join('')}<div class="sheet-footer"><button class="secondary" onclick="aiJsonSheet()">Back</button><button class="primary" id="apply">Apply</button></div>`);$('#apply').onclick=()=>{changes.forEach(x=>{let t=db.tasks.find(t=>t.id===x.task_id);t.ai={exact_message:String(x.exact_message||''),pre_call_brief:String(x.pre_call_brief||''),call_goal:String(x.call_goal||''),next_best_action:String(x.next_best_action||'')};t.type=x.recommended_channel.toLowerCase();t.title=`${t.type==='text'?'Text':'Call'} ${lead(t.leadId).name}`});db.tasks.filter(t=>t.type==='ai_review'&&!t.done&&t.date<=today()).forEach(t=>done(t,'ai-applied'));save();closeSheet();render();toast('AI guidance applied.')}}}
function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download=`leadmate-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}function importData(f){let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!Array.isArray(x.leads)||!Array.isArray(x.tasks))throw 0;localStorage.setItem(KEY,JSON.stringify(x));location.reload()}catch{toast('Invalid LeadMate backup.')}};r.readAsText(f)}
$('#globalAdd').onclick=newLead;$('#newLead').onclick=newLead;$('#addGeneral').onclick=addGeneral;$('#copyDailyPrompt').onclick=()=>copyPrompt();$('#pasteAiJson').onclick=aiJsonSheet;$('#saveContext').onclick=()=>{db.context=$('#businessContext').value;save();toast('Business context saved.')};$('#exportData').onclick=exportData;$('#importData').onchange=e=>{if(e.target.files[0])importData(e.target.files[0]);e.target.value=''};$('#clearData').onclick=()=>{if(confirm('Delete all local data? Export first if needed.')){db=blank();save();render()}};$('#loadDemo').onclick=()=>{if(!confirm('Replace current data with demo data?'))return;let l={id:id(),name:'Dr. Aisha Mehta',contact:'@draishamehta',interest:'ClinicMate',memory:'Values short practical demos.',interactions:[],converted:false,dnc:false,noReply:false};db={version:2,context:'We help clinics save time and grow.',leads:[l],tasks:[]};schedule(l.id,'call',today());save();render();toast('Demo loaded.')};$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.view).classList.add('active')});$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');window.tf=b.dataset.filter;render()});$$('.chip').forEach(b=>b.onclick=()=>{$$('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');window.lf=b.dataset.leadFilter;render()});$('#leadSearch').oninput=render;render();
function loadDetailedDemo(){
  const mk=(name,contact,interest,memory,state='active',history=[])=>({id:id(),name,contact,interest,memory,interactions:history.map(([n,kind,summary])=>({id:id(),date:add(n),kind,summary})),converted:state==='client',dnc:state==='dnc',noReply:state==='paused'});
  const a=mk('Dr. Aisha Mehta','@draishamehta','ClinicMate','Busy expanding her dermatology clinic. Likes concise, practical demonstrations.',['active'][0],[[-9,'sales conversation','Asked how ClinicMate could reduce receptionist workload.'],[-3,'greeting','Said she is in the middle of clinic expansion and asked for a short follow-up.']]);
  const b=mk('Rohan Kapoor','9876543210','Content Mate','Wants patient-education reels. Needs partner approval before committing.','active',[[-7,'sales conversation','Liked the content plan and requested examples.']]);
  const c=mk('Dr. Neel Shah','neel@careplus.in','Online OPD','Converted after a walkthrough. Follow up only as a client success check-in.','client',[[-21,'sales conversation','Booked a product walkthrough.'],[-14,'sales conversation','Confirmed annual plan.']]);
  const d=mk('Maya Wellness','@mayawellness','ReceptionMate','Asked not to be contacted until next quarter.','dnc',[[-28,'sales conversation','Not a priority this quarter; explicitly requested no follow-up.']]);
  const e=mk('Dr. Kavya Rao','kavya@wellness.in','ReceptionMate','Sent two messages; no response. Keep paused unless she re-engages.','paused',[[-18,'sales conversation','Interested in automating appointment confirmations.'],[-12,'text sent','Shared a concise ReceptionMate overview.']]);
  const f=mk('Arjun Malhotra','@arjun.growth','Other — referral partnership','Potential referral partner for independent clinics.','active',[[-1,'sales conversation','Discussed a possible referral partnership and agreed to talk this week.']]);
  db={version:2,context:'We help clinics and health businesses save time and grow with ReceptionMate, Content Mate, ClinicMate, and Online OPD. Be concise, warm, practical, and consultative.',leads:[a,b,c,d,e,f],tasks:[
    {id:id(),leadId:a.id,type:'call',title:'Call Dr. Aisha Mehta',date:today(),done:false,ai:{pre_call_brief:'Aisha is expanding her dermatology clinic and previously asked about reducing front-desk workload.',call_goal:'Agree a 15-minute practical ClinicMate demo.',next_best_action:'Offer two demo slots.'}},
    {id:id(),leadId:b.id,type:'text',title:'Text Rohan Kapoor',date:today(),done:false,ai:{exact_message:'Hi Rohan — sharing a quick thought on the patient-education reels we discussed. Would it help if I sent 3 sample reel ideas for you and your partner to review?',pre_call_brief:'',call_goal:'',next_best_action:'Send examples.'}},
    {id:id(),leadId:f.id,type:'call',title:'Call Arjun Malhotra',date:add(-2),done:false},
    {id:id(),leadId:b.id,type:'text_feedback',title:'Check for a reply from Rohan Kapoor',date:add(-1),done:false,replyChecks:1},
    {id:id(),type:'general',title:'Review this week’s demo bookings',note:'Check calendar, prepare notes, and confirm who needs a reminder.',date:today(),done:false},
    {id:id(),type:'general',title:'Update ClinicMate one-pager',note:'Add the new appointment-flow screenshot.',date:add(2),done:false}
  ]};save();render();toast('Detailed demo data loaded.');
}
$('#loadDemo').onclick=()=>{if(confirm('Replace your current data with detailed demo data? Export first if you want to keep it.'))loadDetailedDemo()};

/* Interaction recording redesign */
function lmStatus(l){return l.status||(l.converted?'paid':l.dnc?'do-not-call':l.noReply?'follow-up':'new')}
function lmLabel(s){return ({new:'New',demo:'Demo',paid:'Paying','follow-up':'Follow-up',followup:'Follow-up','not-interested':'Not interested','do-not-call':'Do not call','cant-afford':'Can’t afford'}[s]||'New')}
function lmContact(l){return [l.phone,l.contact&&/^\+?[\d\s()-]{7,}$/.test(l.contact)?l.contact:'',l.instagram,l.contact?.startsWith('@')?l.contact:'',l.email,l.contact?.includes('@')&&!l.contact.startsWith('@')?l.contact:''].filter((v,i,a)=>v&&a.indexOf(v)===i).join(' · ')||'No contact details'}
function lmFind(q){q=q.trim().toLowerCase();return q?db.leads.filter(l=>`${l.name} ${l.phone||''} ${l.instagram||''} ${l.email||''} ${l.contact||''}`.toLowerCase().includes(q)):[]}
function lmOpts(v,n){return `<div class="option-row" id="${n}">${v.map((x,i)=>`<button type="button" class="option${i?'':' selected'}" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>`}
function lmPick(n){return $(n)?.querySelector('.selected')?.dataset.v}
function lmBind(n,cb){$(n).onclick=e=>{let b=e.target.closest('.option');if(!b)return;$(n).querySelectorAll('.option').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');cb?.(b.dataset.v)}}
function render(){let q=$('#leadSearch').value.toLowerCase(),f=window.lf||'active',ls=db.leads.filter(l=>{let s=lmStatus(l),active=!['paid','do-not-call'].includes(s);return (f==='all'||f===s||(f==='active'&&active))&&`${l.name} ${lmContact(l)}`.toLowerCase().includes(q)});$('#leadList').innerHTML=ls.length?ls.map(l=>`<article class="lead" onclick="profile('${l.id}')"><div class="avatar">${esc(l.name[0]?.toUpperCase()||'?')}</div><div class="lead-info"><strong>${esc(l.name)}</strong><span>${esc(lmContact(l))} · ${l.interactions.length} interactions</span></div><span class="badge">${esc(lmLabel(lmStatus(l)))}</span></article>`).join(''):'<div class="empty">No leads match this view.</div>';let due=db.tasks.filter(t=>!t.done&&!t.archived&&t.date<=today()),calls=due.filter(t=>t.type==='call');$('#taskCount').textContent=`${due.length} item${due.length===1?'':'s'}`;$('#taskSummary').innerHTML=`<span>${calls.length} calls due</span>`;$('#taskList').innerHTML=due.length?due.map(t=>`<article class="task"><button class="check" onclick="openTask('${t.id}')"></button><div class="task-main" onclick="openTask('${t.id}')"><span class="task-type">${esc(t.type)}</span><strong>${esc(t.title)}</strong><p>${esc(t.date)}${t.time?' · '+esc(t.time):''}</p></div><button class="task-action" onclick="openTask('${t.id}')">›</button></article>`).join(''):'<div class="empty">Nothing is due today.</div>';$('#businessContext').value=db.context||'';$('#dateLabel').textContent=new Intl.DateTimeFormat('en',{weekday:'long',month:'short',day:'numeric'}).format(new Date())}
function newLead(){sheet(`<h2>New interaction</h2><p class="intro">Who do you want to interact with?</p><div class="field"><label>Search name, phone, Instagram or email</label><input id="lmSearch" autofocus placeholder="Dr name, phone, @handle, email"></div><div id="lmMatches"></div><div class="sheet-footer"><button class="secondary" onclick="closeSheet()">Cancel</button><button class="primary" id="lmNew">New contact</button></div>`);$('#lmSearch').oninput=()=>{let a=lmFind($('#lmSearch').value);$('#lmMatches').innerHTML=a.length?`<p class="muted">Existing contacts</p>${a.map(l=>`<button class="option" style="width:100%;text-align:left;margin-top:7px" onclick="lmExisting('${l.id}')"><b>${esc(l.name)}</b><br>${esc(lmContact(l))} · ${esc(lmLabel(lmStatus(l)))}</button>`).join('')}`:$('#lmSearch').value?'<p class="muted">No match found. Create a new contact.</p>':''};$('#lmNew').onclick=()=>lmCreate($('#lmSearch').value)}
function lmExisting(i){let l=lead(i),h=l.interactions.slice(-3).reverse().map(x=>`<div class="notice"><b>${esc(x.date)} · ${esc(x.type||x.kind||'Interaction')}</b><br>${esc(x.summary||x.outcome||'Recorded')}</div>`).join('')||'<p class="muted">No prior interactions.</p>';sheet(`<h2>${esc(l.name)}</h2><p class="intro">${esc(lmContact(l))}</p><div class="notice"><b>Status: ${esc(lmLabel(lmStatus(l)))}</b><br>Last interaction: ${esc(l.interactions.at(-1)?.date||'None')}<br>${l.nextAction?`Next action: ${esc(l.nextAction.date)}`:'No scheduled action'}</div><h3>Previous interactions</h3>${h}<div class="sheet-footer"><button class="secondary" onclick="profile('${i}')">View profile</button><button class="primary" onclick="lmStart('${i}')">Continue</button></div>`)}
function lmCreate(seed=''){let phone=/^\+?[\d\s()-]{7,}$/.test(seed),ig=seed.startsWith('@'),email=seed.includes('@')&&!ig;sheet(`<h2>New contact</h2><p class="intro">Add any details you have. One identifier is enough.</p><form id="lmCreate" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${!phone&&!ig&&!email?esc(seed):''}"></div><div class="field"><label>Phone number</label><input name="phone" value="${phone?esc(seed):''}"></div><div class="field"><label>Instagram handle</label><input name="instagram" value="${ig?esc(seed):''}"></div><div class="field"><label>Email</label><input name="email" value="${email?esc(seed):''}"></div><div class="sheet-footer"><button type="button" class="secondary" onclick="newLead()">Back</button><button class="primary">Continue</button></div></form>`);$('#lmCreate').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(!x.name&&!x.phone&&!x.instagram&&!x.email){toast('Add at least one identifier.');return}let d=db.leads.find(l=>['phone','instagram','email'].some(k=>x[k]&&String(l[k]||l.contact||'').toLowerCase()===x[k].trim().toLowerCase()));if(d){lmExisting(d.id);return}let l={id:id(),name:x.name.trim()||'Unnamed lead',phone:x.phone.trim(),instagram:x.instagram.trim(),email:x.email.trim(),contact:x.phone.trim()||x.instagram.trim()||x.email.trim(),interactions:[],status:'new'};db.leads.unshift(l);save();lmType(l.id,true)}}
function lmStart(i){let l=lead(i),p=l.phone||(/^\+?[\d\s()-]{7,}$/.test(l.contact||'')?l.contact:'');if(p){lmType(i,false);return}sheet(`<h2>Phone number not recorded</h2><p class="intro">Add the number if you have it. You may continue without one.</p><div class="field"><label>Phone number</label><input id="lmPhone" inputmode="tel"></div><div class="sheet-footer"><button class="secondary" id="lmSkip">Continue without</button><button class="primary" id="lmSavePhone">Save & continue</button></div>`);$('#lmSkip').onclick=()=>lmType(i,false);$('#lmSavePhone').onclick=()=>{l.phone=$('#lmPhone').value.trim();l.contact=l.phone||l.contact;save();lmType(i,false)}}
function lmType(i,fresh){let choices=fresh?['Booked Call','Cold Call']:['Follow-up Call','Booked Call','Cold Call'];sheet(`<h2>What type of call is this?</h2><p class="intro">${esc(lead(i).name)}</p>${lmOpts(choices,'lmType')}<div class="sheet-footer"><button class="secondary" onclick="profile('${i}')">Cancel</button><button class="primary" id="lmGo">Continue</button></div>`);$('#lmGo').onclick=()=>lmPick('#lmType')==='Booked Call'?lmBooked(i):lmBasic(i,lmPick('#lmType'))}
function lmOutcome(){return `<div class="field"><label>Outcome</label>${lmOpts(['Give me a demo','I want to pay','Not interested','Do not call','Let’s talk later','Can’t afford'],'lmOutcome')}</div><div id="lmOutcomeExtra"></div>`}
function lmWireOutcome(){if(!$('#lmOutcome'))return;lmBind('#lmOutcome',v=>$('#lmOutcomeExtra').innerHTML=v==='Let’s talk later'?`<div class="field"><label>Follow up date</label><input name="callbackDate" type="date" min="${today()}" value="${add(7)}"></div><div class="field"><label>Time</label><input name="callbackTime" type="time"></div>`:v==='Not interested'?'<div class="field"><label>Reason</label><textarea name="reason" placeholder="Why are they not interested?"></textarea></div>':v==='Give me a demo'?'<div class="field"><label>Demo date and time</label><input name="demoDate" type="datetime-local"></div>':v==='I want to pay'?'<div class="field"><label>Payment / onboarding notes</label><textarea name="payment"></textarea></div>':'' )}
function lmBasic(i,type){let l=lead(i),prev=l.interactions.at(-1);sheet(`<h2>${esc(type)}</h2>${type==='Follow-up Call'?`<div class="notice"><b>Previous context</b><br>${esc(prev?`${prev.date}: ${prev.summary||prev.outcome||''}`:'No previous interactions recorded.')}</div>`:'<p class="intro">The detailed format will be added later.</p>'}<form id="lmBasic" class="form-grid"><div class="field"><label>Call notes</label><textarea name="notes" required autofocus placeholder="Record what happened…"></textarea></div>${lmOutcome()}<div class="sheet-footer"><button type="button" class="secondary" onclick="profile('${i}')">Cancel</button><button class="primary">Save interaction</button></div></form>`);lmWireOutcome();$('#lmBasic').onsubmit=e=>{e.preventDefault();lmSave(i,type,Object.fromEntries(new FormData(e.target)),lmPick('#lmOutcome'))}}
function lmBooked(i){let l=lead(i);sheet(`<h2>Booked call</h2><p class="notice">“Hi Dr. ${esc(l.name)}, Kanishk this side. You had shown interest in our Online OPD. Is this a good time to talk?”</p><form id="lmBooked" class="form-grid"><div class="field"><label>Opening outcome</label>${lmOpts(['Yes, available','No, busy','No answer','Asked to call later'],'lmOpening')}</div><div id="lmQual"><div class="field"><label>Where do you practice?</label><input name="location" placeholder="City, state, clinic/hospital"></div><div class="field"><label>What do you practice?</label><input name="specialty" placeholder="Specialty"></div><div class="field"><label>Do you have your own online setup?</label>${lmOpts(['Yes','No','Partial / not sure'],'lmSetup')}</div><div id="lmBranch"></div></div><div id="lmCallBack" hidden><div class="field"><label>Callback date</label><input name="callbackDate" type="date" min="${today()}" value="${add(7)}"></div><div class="field"><label>Callback time</label><input name="callbackTime" type="time"></div></div><div id="lmBookedOutcome">${lmOutcome()}</div><div class="field"><label>Additional Notes</label><textarea name="notes" placeholder="Requirements, objections, preferences, or context"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="profile('${i}')">Cancel</button><button class="primary">Save interaction</button></div></form>`);lmWireOutcome();lmBind('#lmOpening',v=>{$('#lmQual').hidden=v!=='Yes, available';$('#lmCallBack').hidden=v==='Yes, available'||v==='No answer';$('#lmBookedOutcome').hidden=v==='No answer'});lmBind('#lmSetup',v=>{let setup=v==='Yes'||v==='Partial / not sure';$('#lmBranch').innerHTML=`<div class="notice">${setup?'Great. Do you also create content online?':'You must have seen doctors creating content online. Do you also make content?'}</div><div class="field"><label>Creates content?</label>${lmOpts(['Yes','No'],'lmContent')}</div><div id="lmContentBranch"></div>`;lmBind('#lmContent',c=>$('#lmContentBranch').innerHTML=c==='Yes'?'<div class="field"><label>How long have you been creating content?</label><input name="contentDuration"></div><div class="field"><label>Approximate followers</label><input name="followers"></div>':'<div class="field"><label>Are you planning to start creating content?</label>'+lmOpts(['Yes','No'],'lmPlan')+'</div><div class="notice">If they explicitly decline Online OPD, use Not interested below. Otherwise keep the opportunity open.</div>')});$('#lmBooked').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.opening=lmPick('#lmOpening');d.setup=lmPick('#lmSetup');d.content=lmPick('#lmContent');d.planContent=lmPick('#lmPlan');let o=lmPick('#lmOutcome');if(['No, busy','Asked to call later'].includes(d.opening))o='Let’s talk later';if(d.opening==='No answer')o='No answer';lmSave(i,'Booked Call',d,o)}}
function lmSave(i,type,d,outcome){let l=lead(i);l.interactions.push({id:id(),date:today(),type,summary:d.notes||[d.location,d.specialty,d.reason].filter(Boolean).join(' · ')||outcome,outcome,data:d});if(outcome==='Give me a demo'){l.status='demo';if(d.demoDate){let x=new Date(d.demoDate);lmSchedule(i,day(x),x.toTimeString().slice(0,5))}}else if(outcome==='I want to pay'){l.status='paid';lmClose(i)}else if(outcome==='Not interested'){l.status='not-interested';lmClose(i)}else if(outcome==='Do not call'){l.status='do-not-call';lmClose(i)}else if(outcome==='Can’t afford'){l.status='cant-afford';lmClose(i)}else if(outcome==='Let’s talk later'){lmSchedule(i,d.callbackDate||add(7),d.callbackTime||'')}else if(outcome==='No answer')l.status='follow-up';save();closeSheet();render();toast('Interaction recorded.')}
function lmSchedule(i,date,time){let t=db.tasks.find(t=>t.leadId===i&&!t.done&&t.type==='call')||{id:id(),leadId:i,type:'call',done:false};Object.assign(t,{date,time,title:`Follow up with ${lead(i).name}`});if(!db.tasks.includes(t))db.tasks.push(t);lead(i).status='follow-up';lead(i).nextAction={date,time}}
function lmClose(i){db.tasks.filter(t=>t.leadId===i&&!t.done).forEach(t=>t.done=true)}
function profile(i){let l=lead(i),hist=l.interactions.slice().reverse().map(x=>`<div class="notice"><b>${esc(x.date)} · ${esc(x.type||x.kind||'Interaction')} · ${esc(x.outcome||'')}</b><br>${esc(x.summary||'')}</div>`).join('')||'<p class="muted">No interactions yet.</p>';sheet(`<h2>${esc(l.name)}</h2><p class="intro">${esc(lmContact(l))}</p><div class="notice"><b>${esc(lmLabel(lmStatus(l)))}</b>${l.nextAction?`<br>Next: ${esc(l.nextAction.date)} ${esc(l.nextAction.time||'')}`:''}</div><div class="sheet-footer"><button class="secondary" onclick="lmEdit('${i}')">Edit contact</button><button class="primary" onclick="lmStart('${i}')">New interaction</button></div><h3>Interaction history</h3>${hist}`)}
function lmEdit(i){let l=lead(i);sheet(`<h2>Edit contact</h2><form id="lmEdit" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(l.name)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(l.phone||'')}"></div><div class="field"><label>Instagram</label><input name="instagram" value="${esc(l.instagram||'')}"></div><div class="field"><label>Email</label><input name="email" value="${esc(l.email||'')}"></div><div class="sheet-footer"><button class="secondary" type="button" onclick="profile('${i}')">Cancel</button><button class="primary">Save</button></div></form>`);$('#lmEdit').onsubmit=e=>{e.preventDefault();Object.assign(l,Object.fromEntries(new FormData(e.target)));l.contact=l.phone||l.instagram||l.email||l.contact;save();render();profile(i)}}
function openTask(i){let t=db.tasks.find(x=>x.id===i),l=lead(t?.leadId);if(!t||!l){return}sheet(`<h2>Follow-up call</h2><p class="intro">${esc(l.name)} · ${esc(t.date)} ${esc(t.time||'')}</p><div class="sheet-footer"><button class="secondary" onclick="reschedule('${i}')">Reschedule</button><button class="primary" id="lmTaskCall">Record call</button></div>`);$('#lmTaskCall').onclick=()=>{t.done=true;save();lmBasic(l.id,'Follow-up Call')}}
$('#globalAdd').onclick=newLead;$('#newLead').onclick=newLead;$('#leadSearch').oninput=render;$$('.chip').forEach(b=>b.onclick=()=>{$$('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');window.lf=b.dataset.leadFilter;render()});render();

/* Detailed follow-up call format */
function lmRecorded(l,key){for(let x of [...l.interactions].reverse()){let v=x.data?.[key];if(v!==undefined&&v!==null&&v!=='')return v}return 'Not recorded'}
function lmFollowSummary(l){let specialty=lmRecorded(l,'specialty'),location=lmRecorded(l,'location'),setup=lmRecorded(l,'setup'),content=lmRecorded(l,'content'),plan=lmRecorded(l,'planContent'),last=l.interactions.at(-1);let s=`${l.name} practices ${specialty==='Not recorded'?'(specialty not recorded)':specialty}${location==='Not recorded'?'':` in ${location}`}. `;if(setup!=='Not recorded')s+=`Own online setup: ${setup}. `;if(content!=='Not recorded')s+=`Creates content: ${content}. `;if(plan!=='Not recorded')s+=`Plans to create content: ${plan}. `;s+=`Previous outcome: ${last?.outcome||'Not recorded'}.`;return s}
function lmFollowInfo(l){let rows=[['Phone',l.phone||(/^\+?[\d\s()-]{7,}$/.test(l.contact||'')?l.contact:'')],['Instagram',l.instagram||((l.contact||'').startsWith('@')?l.contact:'')],['Specialty',lmRecorded(l,'specialty')],['Practice location',lmRecorded(l,'location')],['Online setup',lmRecorded(l,'setup')],['Creates content',lmRecorded(l,'content')],['Plans content',lmRecorded(l,'planContent')],['Content duration',lmRecorded(l,'contentDuration')],['Followers',lmRecorded(l,'followers')],['Product interest',l.interest||'Not recorded'],['Sales status',lmLabel(lmStatus(l))]];return `<div class="notice"><b>Doctor information</b><br>${rows.map(r=>`${esc(r[0])}: ${esc(r[1]||'Not recorded')}`).join('<br>')}</div>`}
function lmFollowHistory(l){return l.interactions.slice().reverse().map((x,n)=>`<details class="notice" ${n===0?'open':''}><summary><b>${esc(x.date)} · ${esc(x.type||x.kind||'Interaction')} · ${esc(x.outcome||'No outcome')}</b></summary><br><b>Answers / notes</b><br>${esc(x.summary||x.data?.notes||'Not recorded')}<br>${x.data?Object.entries(x.data).filter(([k,v])=>v&&k!=='notes').map(([k,v])=>`${esc(k)}: ${esc(v)}`).join('<br>'):''}${x.nextAction?`<br>Next action: ${esc(x.nextAction.date||x.nextAction)}`:''}</details>`).join('')||'<p class="muted">No previous interactions.</p>'}
function lmFollowIntro(i){let l=lead(i),previous=l.interactions.slice().reverse().find(x=>x.data?.notes||x.summary);sheet(`<h2>Follow-up call</h2><p class="intro">Review the recorded information before starting a new call record.</p>${lmFollowInfo(l)}<div class="notice"><b>Previous interaction summary</b><br>${esc(lmFollowSummary(l))}</div>${previous?`<div class="notice"><b>Previous notes (read only)</b><br>${esc(previous.data?.notes||previous.summary||'Not recorded')}</div>`:''}<h3>Previous interactions</h3>${lmFollowHistory(l)}<div class="sheet-footer"><button class="secondary" onclick="profile('${i}')">Back</button><button class="primary" onclick="lmFollowForm('${i}')">Start Follow-up Call</button></div>`)}
function lmFollowExtra(v){let e=$('#lmFollowExtra');if(!e)return;if(v==='Wants to pay')e.innerHTML=`<div class="field"><label>Product</label><input name="product"></div><div class="field"><label>Quoted price</label><input name="quotedPrice"></div><div class="field"><label>Payment link sent?</label>${lmOpts(['Yes','No'],'lmPaymentLink')}</div><div class="field"><label>Payment status</label>${lmOpts(['Pending','Paid','Not sent'],'lmPaymentStatus')}</div><div class="field"><label>Next action</label><input name="nextAction"></div>`;else if(v==='Wants a demo')e.innerHTML=`<div class="field"><label>Product to demonstrate</label><input name="product"></div><div class="field"><label>Demo date and time</label><input name="demoDate" type="datetime-local"></div><div class="field"><label>Demo status</label>${lmOpts(['To schedule','Scheduled','Completed'],'lmDemoStatus')}</div><div class="field"><label>Next action</label><input name="nextAction"></div>`;else if(v==='Will let you know')e.innerHTML=`<div class="field"><label>Reason for delaying</label><textarea name="delayReason"></textarea></div><div class="field"><label>Agreed to future contact?</label>${lmOpts(['Yes','No'],'lmFutureContact')}</div><div class="field" id="lmFutureDate"><label>Next follow-up date</label><input name="callbackDate" type="date" min="${today()}"></div>`;else if(v==='Asked to call later')e.innerHTML=`<div class="field"><label>When should we call again?</label>${lmOpts(['Did not give a date','Specific date','In one week','Next month'],'lmWhen')}</div><div id="lmWhenDate"></div><div class="field"><label>Next action if no date was given</label>${lmOpts(['Occasional follow-up list','No action'],'lmNoDateAction')}</div>`;else if(v==='Not interested')e.innerHTML='<div class="field"><label>Why is the doctor not interested?</label><textarea name="reason" required></textarea></div><div class="field"><label>Relevant product</label><input name="product" placeholder="e.g. Online OPD"></div>';else if(v==='Other')e.innerHTML='<div class="field"><label>Outcome details</label><textarea name="otherOutcome" required></textarea></div><div class="field"><label>Next action</label><input name="nextAction"></div>';else e.innerHTML='';if(v==='Will let you know'){lmBind('#lmFutureContact',a=>$('#lmFutureDate').hidden=a!=='Yes')}if(v==='Asked to call later'){lmBind('#lmWhen',a=>{$('#lmWhenDate').innerHTML=a==='Specific date'||a==='Next month'?`<div class="field"><label>Callback date and time</label><input name="callbackDate" type="date" min="${today()}" value="${a==='Next month'?(()=>{let d=new Date(today()+'T12:00:00');d.setMonth(d.getMonth()+1);return day(d)})():''}"><input name="callbackTime" type="time"></div>`:''})}}
function lmFollowForm(i){let l=lead(i);sheet(`<h2>Record follow-up call</h2><p class="intro">No script — record only what happened.</p><form id="lmFollowForm" class="form-grid"><div class="field"><label>Call connected?</label>${lmOpts(['Yes','No'],'lmConnected')}</div><div id="lmConnectedNo" hidden><div class="field"><label>Call outcome</label>${lmOpts(['No answer','Busy','Switched off / unreachable','Invalid number','Other'],'lmNoConnectOutcome')}</div><div class="field"><label>Retry / next action</label>${lmOpts(['No action','Retry in one week','Choose a date'],'lmRetry')}</div><div id="lmRetryDate"></div></div><div id="lmConnectedYes"><div class="field"><label>Could you speak to the doctor?</label>${lmOpts(['Yes','No'],'lmSpeak')}</div><div id="lmCannotSpeak" hidden><div class="field"><label>Reason</label><textarea name="speakReason"></textarea></div><div class="field"><label>Next action</label>${lmOpts(['No action','Call later','Choose a date'],'lmSpeakNext')}</div><div id="lmSpeakDate"></div></div><div id="lmConversation"><div class="field"><label>Outcome of the call</label>${lmOpts(['Wants to pay','Wants a demo','Will let you know','Asked to call later','Not interested','Other'],'lmFollowOutcome')}</div><div id="lmFollowExtra"></div></div></div><div class="field"><label>Additional Notes</label><textarea name="notes" placeholder="Requirements, objections, preferences, or context"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="lmFollowIntro('${i}')">Back to history</button><button class="primary">Save Interaction</button></div></form>`);let connected=v=>{$('#lmConnectedNo').hidden=v==='Yes';$('#lmConnectedYes').hidden=v!=='Yes'};lmBind('#lmConnected',connected);lmBind('#lmRetry',v=>$('#lmRetryDate').innerHTML=v==='Choose a date'?`<div class="field"><label>Retry date and time</label><input name="retryDate" type="date" min="${today()}"><input name="retryTime" type="time"></div>`:'');let speak=v=>{$('#lmCannotSpeak').hidden=v==='Yes';$('#lmConversation').hidden=v!=='Yes'};lmBind('#lmSpeak',speak);lmBind('#lmSpeakNext',v=>$('#lmSpeakDate').innerHTML=v==='Choose a date'?`<div class="field"><label>Callback date and time</label><input name="callbackDate" type="date" min="${today()}"><input name="callbackTime" type="time"></div>`:'');lmBind('#lmFollowOutcome',lmFollowExtra);lmFollowExtra('Wants to pay');$('#lmFollowForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),connected=lmPick('#lmConnected'),spoke=connected==='Yes'?lmPick('#lmSpeak'):'No',outcome=connected==='No'?lmPick('#lmNoConnectOutcome'):spoke==='No'?'Could not speak to doctor':lmPick('#lmFollowOutcome');if(outcome==='Not interested'&&!d.reason.trim()){toast('Please record why they are not interested.');return}d.connected=connected;d.spokeToDoctor=spoke;d.outcome=outcome;d.paymentLinkSent=lmPick('#lmPaymentLink');d.paymentStatus=lmPick('#lmPaymentStatus');d.demoStatus=lmPick('#lmDemoStatus');d.futureContact=lmPick('#lmFutureContact');d.when=lmPick('#lmWhen');d.retry=lmPick('#lmRetry');d.speakNext=lmPick('#lmSpeakNext');lmSaveFollow(i,d)}}
function lmSaveFollow(i,d){let l=lead(i),o=d.outcome,callback='';if(d.retry==='Retry in one week')callback=add(7);if(d.retry==='Choose a date')callback=d.retryDate;if(d.speakNext==='Call later')callback=add(7);if(d.speakNext==='Choose a date')callback=d.callbackDate;if(o==='Will let you know'&&d.futureContact==='Yes')callback=d.callbackDate;if(o==='Asked to call later'){if(d.when==='In one week')callback=add(7);if(['Specific date','Next month'].includes(d.when))callback=d.callbackDate}if(o==='Wants a demo'&&d.demoDate){let x=new Date(d.demoDate);callback=day(x);d.callbackTime=x.toTimeString().slice(0,5)}l.interactions.push({id:id(),date:today(),type:'Follow-up Call',summary:d.notes||d.reason||o,outcome:o,data:d,nextAction:callback?{date:callback,time:d.callbackTime||''}:null});if(o==='Wants a demo')l.status='demo';else if(o==='Wants to pay'&&d.paymentStatus==='Paid'){l.status='paid';lmClose(i)}else if(o==='Not interested')l.status='not-interested';else if(o==='Invalid number')l.status='follow-up';if(callback)lmSchedule(i,callback,d.callbackTime||d.retryTime||'');save();render();lmFollowIntro(i);toast('Follow-up interaction saved.')}
function lmBasic(i,type){if(type==='Follow-up Call'){lmFollowIntro(i);return}let l=lead(i);sheet(`<h2>${esc(type)}</h2><p class="intro">The detailed format will be added later.</p><form id="lmBasic" class="form-grid"><div class="field"><label>Call notes</label><textarea name="notes" required autofocus placeholder="Record what happened…"></textarea></div>${lmOutcome()}<div class="field"><label>Additional Notes</label><textarea name="additionalNotes"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="profile('${i}')">Cancel</button><button class="primary">Save interaction</button></div></form>`);lmWireOutcome();$('#lmBasic').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.notes=[d.notes,d.additionalNotes].filter(Boolean).join('\n');lmSave(i,type,d,lmPick('#lmOutcome'))}}

/* Booked-call live conversation guide: deliberately one question at a time. */
function lmBooked(i){let l=lead(i),s={step:'opening',opening:'',location:'',specialty:'',setup:'',content:'',duration:'',followers:'',planning:'',contentMateShared:false,outcome:'',notes:'',callbackChoice:'No date given',callbackDate:'',callbackTime:'',reason:'',product:'',paymentStatus:'Pending',demoDetails:'',demoStatus:'',otherOutcome:'',nextAction:''};let back={callback:'opening',location:'opening',specialty:'location',setup:'specialty',pitch:'setup',content:'pitch',duration:'content',followers:'duration',planning:'content',contentmate:'planning',offline:'planning',outcome:'followers'};
  const nav=(to)=>{s.step=to;draw()};const field=(label,name,placeholder='')=>`<div class="field"><label>${label}</label><input id="bcField" value="${esc(s[name]||'')}" placeholder="${placeholder}"></div>`;const notes=()=>`<div class="field"><label>Additional Notes</label><textarea id="bcNotes" placeholder="Requirements, objections, preferences, or context">${esc(s.notes)}</textarea></div>`;const footer=(next,prev=true)=>`<div class="sheet-footer">${prev?`<button type="button" class="secondary" id="bcBack">Back</button>`:`<button type="button" class="secondary" onclick="profile('${i}')">Cancel</button>`}<button class="primary" id="bcNext">${next}</button></div>`;const selected=(n,v)=>{if(!v||!$(n))return;$(n).querySelectorAll('.option').forEach(x=>x.classList.toggle('selected',x.dataset.v===v))};
  function keep(){let n=$('#bcNotes');if(n)s.notes=n.value;let f=$('#bcField');if(f){let key=f.dataset.key;if(key)s[key]=f.value}let d=$('#bcCallbackDate'),t=$('#bcCallbackTime');if(d)s.callbackDate=d.value;if(t)s.callbackTime=t.value}
  function common(html,next,go,prev=true){sheet(`<h2>Booked call</h2>${html}${notes()}${footer(next,prev)}`);let n=$('#bcNotes');if(n)n.oninput=()=>s.notes=n.value;let f=$('#bcField');if(f){f.dataset.key=go?.key||'';f.oninput=()=>s[f.dataset.key]=f.value}$('#bcNext').onclick=()=>{keep();if(go?.required&&!s[go.key].trim()){toast('Please record the answer.');return}go?.run?.();};let b=$('#bcBack');if(b)b.onclick=()=>{keep();nav(back[s.step]||'opening')}}
  function outcomeFields(){let x=s.outcome;if(x==='Not interested')return field('Reason','reason','Why are they not interested?');if(x==='Wants to pay')return `<div class="field"><label>Product</label><input id="bcProduct" value="${esc(s.product)}"></div><div class="field"><label>Payment status</label>${lmOpts(['Pending','Paid','Not paid'],'bcPayment')}</div>`;if(x==='Wants a demo')return `<div class="field"><label>Demo details</label><textarea id="bcDemo">${esc(s.demoDetails)}</textarea></div><div class="field"><label>Demo status</label>${lmOpts(['To schedule','Scheduled','Completed'],'bcDemoStatus')}</div>`;if(x==='Asked to call later')return `<div class="field"><label>When should we call again?</label>${lmOpts(['No date given','Specific date','In one week','Next month'],'bcCallback')}</div><div id="bcDate"></div>`;if(x==='Will let me know.')return field('Agreed next action','nextAction');if(x==='Other')return field('Outcome','otherOutcome');return ''}
  function bcSave(){keep();if(s.callbackChoice==='Specific date'&&!s.callbackDate){toast('Please record the callback date.');return}let o=s.outcome,lx=lead(i),callback='';if(s.opening==='No'){if(s.callbackChoice==='Specific date')callback=s.callbackDate;else if(s.callbackChoice==='In one week')callback=add(7);else if(s.callbackChoice==='Next month'){let d=new Date(today()+'T12:00:00');d.setMonth(d.getMonth()+1);callback=day(d)}}if(o==='Asked to call later'){if(s.callbackChoice==='Specific date')callback=s.callbackDate;else if(s.callbackChoice==='In one week')callback=add(7);else if(s.callbackChoice==='Next month'){let d=new Date(today()+'T12:00:00');d.setMonth(d.getMonth()+1);callback=day(d)}}let outcome=s.opening==='No'?'Asked to call later':o;let data={...s,callbackDate:callback,callbackTime:s.callbackTime};lx.location=s.location||lx.location;lx.specialty=s.specialty||lx.specialty;lx.interactions.push({id:id(),date:today(),type:'Booked Call',summary:s.notes||s.reason||outcome||'Booked call recorded',outcome,data,nextAction:callback?{date:callback,time:s.callbackTime}:null});if(outcome==='Wants a demo')lx.status='demo';else if(outcome==='Wants to pay'&&s.paymentStatus==='Paid'){lx.status='paid';lmClose(i)}else if(outcome==='Not interested')lx.status='not-interested';else if(outcome==='Do not contact'){lx.status='do-not-call';lmClose(i)};if(callback)lmSchedule(i,callback,s.callbackTime);save();render();profile(i);toast('Booked call saved.')}
  function draw(){if(s.step==='opening'){common(`<p class="notice">SAY: “Hi, Doctor. Kanishk this side. Is this a good time to talk?”</p><div class="field"><label>Is this a good time?</label>${lmOpts(['Yes','No'],'bcOpening')}</div>`,'Continue',{run:()=>nav(lmPick('#bcOpening')==='Yes'?'location':'callback')},false);lmBind('#bcOpening',v=>s.opening=v);selected('#bcOpening',s.opening);return}if(s.step==='callback'){common(`<p class="notice">ASK: “When would be a good time to call you back?”</p><div class="field"><label>Callback timing</label>${lmOpts(['No date given','Specific date','In one week','Next month'],'bcCallback')}</div><div id="bcDate"></div>`,'Save interaction',{run:bcSave});lmBind('#bcCallback',v=>{s.callbackChoice=v;$('#bcDate').innerHTML=v==='Specific date'?`<div class="field"><label>Date and time</label><input id="bcCallbackDate" type="date" min="${today()}" value="${esc(s.callbackDate)}"><input id="bcCallbackTime" type="time" value="${esc(s.callbackTime)}"></div>`:''});selected('#bcCallback',s.callbackChoice);return}if(s.step==='location'){common(`<p class="notice">ASK: “Where do you currently practice?”</p>${field('Practice location','location')}`,'Continue',{key:'location',required:true,run:()=>nav('specialty')});return}if(s.step==='specialty'){common(`<p class="notice">ASK: “What do you practice, Doctor?”</p>${field('Specialty','specialty')}`,'Continue',{key:'specialty',required:true,run:()=>nav('setup')});return}if(s.step==='setup'){common(`<p class="notice">ASK: “Do you have your own setup?”</p><div class="field">${lmOpts(['Yes','No'],'bcSetup')}</div>`,'Continue',{run:()=>{s.setup=lmPick('#bcSetup');nav(s.setup==='No'?'pitch':'content')}});lmBind('#bcSetup',v=>s.setup=v);selected('#bcSetup',s.setup);return}if(s.step==='pitch'){common(`<p class="notice">SAY: “We basically make Online OPDs, where you have an online address that patients can visit to book appointments.”</p>`,'Continue',{run:()=>nav('content')});return}if(s.step==='content'){common(`<p class="notice">ASK: “Do you also make content?”</p><div class="field">${lmOpts(['Yes','No'],'bcContent')}</div>`,'Continue',{run:()=>{s.content=lmPick('#bcContent');nav(s.content==='Yes'?'duration':'planning')}});lmBind('#bcContent',v=>s.content=v);selected('#bcContent',s.content);return}if(s.step==='duration'){common(`<p class="notice">ASK: “How long have you been creating content?”</p>${field('Content creation duration','duration')}`,'Continue',{key:'duration',required:true,run:()=>nav('followers')});return}if(s.step==='followers'){common(`<p class="notice">ASK: “How many followers do you have?”</p>${field('Follower count','followers')}`,'Continue',{key:'followers',required:true,run:()=>nav('outcome')});return}if(s.step==='planning'){common(`<p class="notice">ASK: “Are you planning to start creating content?”</p><div class="field">${lmOpts(['Yes','No'],'bcPlanning')}</div>`,'Continue',{run:()=>{s.planning=lmPick('#bcPlanning');nav(s.planning==='Yes'?'contentmate':'offline')}});lmBind('#bcPlanning',v=>s.planning=v);selected('#bcPlanning',s.planning);return}if(s.step==='contentmate'){common(`<p class="notice">Share the ContentMate link.</p><button type="button" class="option ${s.contentMateShared?'selected':''}" id="bcShared">${s.contentMateShared?'ContentMate link shared':'Mark ContentMate link as shared'}</button>`,'Continue',{run:()=>nav('outcome')});$('#bcShared').onclick=()=>{s.contentMateShared=!s.contentMateShared;draw()};return}if(s.step==='offline'){common(`<p class="notice">SAY: Explain that MedCortico can help with the doctor's offline clinic setup.</p>`,'Continue',{run:()=>nav('outcome')});return}if(s.step==='outcome'){back.outcome=s.content==='Yes'?'followers':s.planning==='Yes'?'contentmate':'offline';common(`<div class="field"><label>Call outcome</label>${lmOpts(['Will let me know.','Not interested','Wants to pay','Wants a demo','Asked to call later','Do not contact','Other'],'bcOutcome')}</div><div id="bcOutcomeFields"></div>`,'Save interaction',{run:()=>{if(s.outcome==='Not interested'&&!s.reason.trim()){toast('Please record the reason.');return}bcSave()}});let renderOutcome=v=>{s.outcome=v;$('#bcOutcomeFields').innerHTML=outcomeFields();if(v==='Wants to pay'){lmBind('#bcPayment',a=>s.paymentStatus=a);selected('#bcPayment',s.paymentStatus);$('#bcProduct').oninput=e=>s.product=e.target.value}if(v==='Wants a demo'){$('#bcDemo').oninput=e=>s.demoDetails=e.target.value;lmBind('#bcDemoStatus',a=>s.demoStatus=a);selected('#bcDemoStatus',s.demoStatus)}if(v==='Asked to call later'){lmBind('#bcCallback',a=>{s.callbackChoice=a;$('#bcDate').innerHTML=a==='Specific date'?`<div class="field"><label>Date and time</label><input id="bcCallbackDate" type="date" min="${today()}"><input id="bcCallbackTime" type="time"></div>`:''});selected('#bcCallback',s.callbackChoice)}let f=$('#bcField');if(f){f.dataset.key=v==='Not interested'?'reason':v==='Other'?'otherOutcome':'nextAction';f.oninput=()=>s[f.dataset.key]=f.value}};lmBind('#bcOutcome',renderOutcome);renderOutcome(s.outcome||'Will let me know.');selected('#bcOutcome',s.outcome);return}}
  draw()
}

/* Cold-call live conversation guide. */
function lmCold(i){let l=lead(i),s={step:'opening',good:'',interested:'',location:'',specialty:'',setup:'',content:'',duration:'',followers:'',planning:'',contentMateShared:false,outcome:'',notes:'',callbackChoice:'Doctor did not give a date',callbackDate:'',callbackTime:'',reason:'',product:'',paymentStatus:'Pending',demoDetails:'',demoStatus:'',otherOutcome:'',nextAction:''},back={callback:'opening',opd:'opening',interest:'opd',location:'interest',specialty:'location',setup:'specialty',content:'setup',duration:'content',followers:'duration',planning:'content',contentmate:'planning',offline:'planning',outcome:'followers'};
 const nav=x=>{s.step=x;draw()}, picked=(n,v)=>{if(!v||!$(n))return;$(n).querySelectorAll('.option').forEach(x=>x.classList.toggle('selected',x.dataset.v===v))}, notes=()=>`<div class="field"><label>Additional Notes</label><textarea id="ccNotes" placeholder="Requirements, objections, preferences, or context">${esc(s.notes)}</textarea></div>`, field=(label,key)=>`<div class="field"><label>${label}</label><input id="ccField" data-key="${key}" value="${esc(s[key]||'')}"></div>`, footer=(label,canBack=true)=>`<div class="sheet-footer">${canBack?'<button class="secondary" id="ccBack">Back</button>':`<button class="secondary" onclick="profile('${i}')">Cancel</button>`}<button class="primary" id="ccNext">${label}</button></div>`;
 function keep(){let n=$('#ccNotes'),f=$('#ccField'),d=$('#ccDate'),t=$('#ccTime');if(n)s.notes=n.value;if(f)s[f.dataset.key]=f.value;if(d)s.callbackDate=d.value;if(t)s.callbackTime=t.value}
 function screen(body,label,run,canBack=true){sheet(`<h2>Cold call</h2>${body}${notes()}${footer(label,canBack)}`);$('#ccNotes').oninput=e=>s.notes=e.target.value;$('#ccNext').onclick=()=>{keep();run()};let b=$('#ccBack');if(b)b.onclick=()=>{keep();nav(back[s.step]||'opening')}}
 function callbackOptions(){return `<div class="field"><label>Callback timing</label>${lmOpts(['Specific date and time','In one week','Next month','Doctor did not give a date'],'ccCallback')}</div><div id="ccDateWrap"></div>`}
 function callbackWire(){lmBind('#ccCallback',v=>{s.callbackChoice=v;$('#ccDateWrap').innerHTML=v==='Specific date and time'?`<div class="field"><label>Date and time</label><input id="ccDate" type="date" min="${today()}" value="${esc(s.callbackDate)}"><input id="ccTime" type="time" value="${esc(s.callbackTime)}"></div>`:''});picked('#ccCallback',s.callbackChoice)}
 function outcomeFields(){let o=s.outcome;if(o==='Not interested')return field('Reason','reason');if(o==='Wants to pay')return `<div class="field"><label>Product</label><input id="ccProduct" value="${esc(s.product)}"></div><div class="field"><label>Payment status</label>${lmOpts(['Pending','Paid','Not paid'],'ccPayment')}</div>`;if(o==='Wants a demo')return `<div class="field"><label>Demo details</label><textarea id="ccDemo">${esc(s.demoDetails)}</textarea></div><div class="field"><label>Demo status</label>${lmOpts(['To schedule','Scheduled','Completed'],'ccDemoStatus')}</div>`;if(o==='Asked to call later')return callbackOptions();if(o==='Will let me know.')return field('Agreed next action','nextAction');if(o==='Other')return field('Outcome','otherOutcome');return ''}
 function ccSave(){keep();if(s.callbackChoice==='Specific date and time'&&!s.callbackDate){toast('Please record the callback date.');return}let callback='';if(['No','Asked to call later'].includes(s.good==='No'?'No':s.outcome)){if(s.callbackChoice==='Specific date and time')callback=s.callbackDate;else if(s.callbackChoice==='In one week')callback=add(7);else if(s.callbackChoice==='Next month'){let d=new Date(today()+'T12:00:00');d.setMonth(d.getMonth()+1);callback=day(d)}}let outcome=s.good==='No'?'Asked to call later':s.outcome,lx=lead(i),data={...s,callbackDate:callback,callbackTime:s.callbackTime};lx.location=s.location||lx.location;lx.specialty=s.specialty||lx.specialty;lx.interactions.push({id:id(),date:today(),type:'Cold Call',summary:s.notes||s.reason||outcome||'Cold call recorded',outcome,data,nextAction:callback?{date:callback,time:s.callbackTime}:null});if(outcome==='Wants a demo')lx.status='demo';else if(outcome==='Wants to pay'&&s.paymentStatus==='Paid'){lx.status='paid';lmClose(i)}else if(outcome==='Not interested')lx.status='not-interested';else if(outcome==='Do not contact'){lx.status='do-not-call';lmClose(i)}if(callback)lmSchedule(i,callback,s.callbackTime);save();render();profile(i);toast('Cold call saved.')}
 function draw(){if(s.step==='opening'){let script=l.enquiry?'“Hello, Doctor. Kanishk this side from MedCortico. We received your query about setting up an Online OPD. Is this a good time to talk about it?”':'“Hello, Doctor. Kanishk this side from MedCortico. Is this a good time to talk about Online OPD?”';screen(`<p class="notice">SAY: ${script}</p><div class="field"><label>Is this a good time to talk?</label>${lmOpts(['Yes','No'],'ccGood')}</div>`,'Continue',()=>nav(lmPick('#ccGood')==='Yes'?'opd':'callback'),false);lmBind('#ccGood',v=>s.good=v);picked('#ccGood',s.good);return}if(s.step==='callback'){screen(`<p class="notice">SAY: “No problem, Doctor. When would be a good time to call you back?”</p>${callbackOptions()}`,'Save interaction',ccSave);callbackWire();return}if(s.step==='opd'){screen(`<p class="notice">SAY: “Okay, Doctor. We basically set up Online OPDs for doctors. It gives you an online address where patients can visit, view your available slots and book appointments. Depending on the setup, patients can also make payments and access teleconsultations.”</p>`,'Continue',()=>nav('interest'));return}if(s.step==='interest'){screen(`<p class="notice">ASK: “Are you interested in setting up an Online OPD?”</p><div class="field">${lmOpts(['Yes','No'],'ccInterested')}</div>`,'Continue',()=>{s.interested=lmPick('#ccInterested');nav(s.interested==='Yes'?'location':'outcome')});lmBind('#ccInterested',v=>s.interested=v);picked('#ccInterested',s.interested);return}if(s.step==='location'){screen(`<p class="notice">ASK: “Where do you currently practice, Doctor?”</p>${field('Practice location','location')}`,'Continue',()=>{if(!s.location.trim())return toast('Please record the answer.');nav('specialty')});return}if(s.step==='specialty'){screen(`<p class="notice">ASK: “What do you practice, Doctor?”</p>${field('Specialty','specialty')}`,'Continue',()=>{if(!s.specialty.trim())return toast('Please record the answer.');nav('setup')});return}if(s.step==='setup'){screen(`<p class="notice">ASK: “Do you have your own setup?”</p><div class="field">${lmOpts(['Yes','No'],'ccSetup')}</div>`,'Continue',()=>{s.setup=lmPick('#ccSetup');nav('content')});lmBind('#ccSetup',v=>s.setup=v);picked('#ccSetup',s.setup);return}if(s.step==='content'){screen(`<p class="notice">ASK: “Do you also make content?”</p><div class="field">${lmOpts(['Yes','No'],'ccContent')}</div>`,'Continue',()=>{s.content=lmPick('#ccContent');nav(s.content==='Yes'?'duration':'planning')});lmBind('#ccContent',v=>s.content=v);picked('#ccContent',s.content);return}if(s.step==='duration'){screen(`<p class="notice">ASK: “How long have you been creating content?”</p>${field('Content creation duration','duration')}`,'Continue',()=>{if(!s.duration.trim())return toast('Please record the answer.');nav('followers')});return}if(s.step==='followers'){screen(`<p class="notice">ASK: “How many followers do you have?”</p>${field('Follower count','followers')}`,'Continue',()=>{if(!s.followers.trim())return toast('Please record the answer.');nav('outcome')});return}if(s.step==='planning'){screen(`<p class="notice">ASK: “Are you planning to start creating content?”</p><div class="field">${lmOpts(['Yes','No'],'ccPlanning')}</div>`,'Continue',()=>{s.planning=lmPick('#ccPlanning');nav(s.planning==='Yes'?'contentmate':'offline')});lmBind('#ccPlanning',v=>s.planning=v);picked('#ccPlanning',s.planning);return}if(s.step==='contentmate'){screen(`<p class="notice">SAY: “Great, Doctor. We also have ContentMate, which may be useful when you start creating content. I'll share the link with you.”</p><button type="button" class="option ${s.contentMateShared?'selected':''}" id="ccShared">${s.contentMateShared?'ContentMate link shared':'Mark ContentMate link as shared'}</button>`,'Continue',()=>nav('outcome'));$('#ccShared').onclick=()=>{s.contentMateShared=!s.contentMateShared;draw()};return}if(s.step==='offline'){screen(`<p class="notice">SAY: “Understood, Doctor. We can also help with the digital setup of your offline clinic.”</p>`,'Continue',()=>nav('outcome'));return}if(s.step==='outcome'){back.outcome=s.interested==='No'?'interest':s.content==='Yes'?'followers':s.planning==='Yes'?'contentmate':'offline';screen(`<div class="field"><label>Call outcome</label>${lmOpts(['Will let me know.','Not interested','Wants to pay','Wants a demo','Asked to call later','Do not contact','Other'],'ccOutcome')}</div><div id="ccOutcomeFields"></div>`,'Save interaction',()=>{if(s.outcome==='Not interested'&&!s.reason.trim())return toast('Please record the reason.');ccSave()});let show=v=>{s.outcome=v;$('#ccOutcomeFields').innerHTML=outcomeFields();if(v==='Wants to pay'){$('#ccProduct').oninput=e=>s.product=e.target.value;lmBind('#ccPayment',a=>s.paymentStatus=a);picked('#ccPayment',s.paymentStatus)}if(v==='Wants a demo'){$('#ccDemo').oninput=e=>s.demoDetails=e.target.value;lmBind('#ccDemoStatus',a=>s.demoStatus=a);picked('#ccDemoStatus',s.demoStatus)}if(v==='Asked to call later')callbackWire()};lmBind('#ccOutcome',show);show(s.outcome||'Will let me know.');picked('#ccOutcome',s.outcome);return}}
 draw()
}
function lmBasic(i,type){if(type==='Follow-up Call'){lmFollowIntro(i);return}if(type==='Cold Call'){lmCold(i);return}let l=lead(i);sheet(`<h2>${esc(type)}</h2><p class="intro">The detailed format will be added later.</p><form id="lmBasic" class="form-grid"><div class="field"><label>Call notes</label><textarea name="notes" required autofocus placeholder="Record what happened…"></textarea></div>${lmOutcome()}<div class="field"><label>Additional Notes</label><textarea name="additionalNotes"></textarea></div><div class="sheet-footer"><button type="button" class="secondary" onclick="profile('${i}')">Cancel</button><button class="primary">Save interaction</button></div></form>`);lmWireOutcome();$('#lmBasic').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.notes=[d.notes,d.additionalNotes].filter(Boolean).join('\n');lmSave(i,type,d,lmPick('#lmOutcome'))}}
